<?php $pageTitle='Product Management'; require '../includes/functions.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ if(isset($_POST['delete'])){$pdo->prepare('UPDATE products SET is_archived=1 WHERE id=?')->execute([$_POST['id']]);} else { $image=$_POST['old_image']??'assets/images/product-placeholder.svg'; if(!empty($_FILES['image']['name'])){ $ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION)); if(in_array($ext,['png','jpg','jpeg','svg'])){ $image='uploads/product_'.time().'.'.$ext; move_uploaded_file($_FILES['image']['tmp_name'],'../'.$image); }} if(!empty($_POST['id'])){$pdo->prepare('UPDATE products SET category_id=?,name=?,description=?,price=?,stock=?,low_stock_level=?,image=? WHERE id=?')->execute([$_POST['category_id'],$_POST['name'],$_POST['description'],$_POST['price'],$_POST['stock'],$_POST['low_stock_level'],$image,$_POST['id']]);} else {$pdo->prepare('INSERT INTO products (category_id,name,description,price,stock,low_stock_level,image) VALUES (?,?,?,?,?,?,?)')->execute([$_POST['category_id'],$_POST['name'],$_POST['description'],$_POST['price'],$_POST['stock'],$_POST['low_stock_level'],$image]);}} redirect('products.php'); }
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$_GET['edit']]);$edit=$s->fetch();} $cats=$pdo->query('SELECT * FROM categories')->fetchAll(); $products=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_archived=0 ORDER BY p.id DESC')->fetchAll(); require '_header.php'; ?>
<h1 class="fw-bold mb-4">Product Management</h1><div class="row g-4"><div class="col-lg-4"><form method="post" enctype="multipart/form-data" class="bg-white p-4 rounded-4 shadow-sm"><h4><?= $edit?'Edit':'Add' ?> Product</h4><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><input type="hidden" name="old_image" value="<?= e($edit['image']??'') ?>"><select name="category_id" class="form-select mb-2"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= ($edit['category_id']??0)==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><input name="name" class="form-control mb-2" placeholder="Product name" value="<?= e($edit['name']??'') ?>" required><textarea name="description" class="form-control mb-2" placeholder="Description"><?= e($edit['description']??'') ?></textarea><input name="price" type="number" step="0.01" class="form-control mb-2" placeholder="Price" value="<?= e($edit['price']??'') ?>"><input name="stock" type="number" class="form-control mb-2" placeholder="Stock" value="<?= e($edit['stock']??'') ?>"><input name="low_stock_level" type="number" class="form-control mb-2" placeholder="Low stock level" value="<?= e($edit['low_stock_level']??5) ?>"><img id="preview" src="../<?= e($edit['image']??'assets/images/product-placeholder.svg') ?>" class="img-fluid rounded mb-2" alt="preview"><input name="image" type="file" class="form-control image-input mb-3" data-preview="#preview"><button class="btn btn-red w-100">Save Product</button></form></div><div class="col-lg-8"><div class="table-responsive"><table class="table bg-white"><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><img src="../<?= e($p['image']) ?>" width="55"></td><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td><?= money($p['price']) ?></td><td><?= $p['stock'] ?></td><td><a class="btn btn-sm btn-yellow" href="?edit=<?= $p['id'] ?>">Edit</a><form method="post" class="d-inline"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button name="delete" class="btn btn-sm btn-outline-danger">Archive</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php require '_footer.php'; ?>